const labels=['FOCUS','ATTITUDE','LEADERSHIP','CITIZENSHIP','ORGANIZATION','NON-VIOLENCE'];
let stops=[],timer,travelTimer;let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const main=document.querySelector('main');const motion=document.querySelector('#motion');
function setMotion(){document.body.classList.toggle('reduced',reduced);motion.textContent=`Motion: ${reduced?'off':'on'}`;motion.setAttribute('aria-pressed',String(reduced))}setMotion();motion.onclick=()=>{reduced=!reduced;setMotion()};
function position(i){return `${i%4*100/3}% ${Math.floor(i/4)*50}%`}
function scene(i,cls='scene'){return `<div class="${cls}" role="img" aria-label="${['Falcon student listening in class','Falcon students walking calmly in line','Falcon student washing hands','Falcon students taking turns with a ball','Falcon student sitting safely at lunch','Falcon student applauding a performance','Falcon student reading gently','Falcon student painting carefully','Falcon students playing fairly','Falcon students building together','Falcon student carefully using a computer'][i]}" style="background-position:${position(i)}"></div>`}
function home(){clearInterval(timer);main.innerHTML=`<section class="hero"><div><span class="eyebrow">WELCOME, LITTLE TRAVELERS</span><h1>All Aboard the<br><em>Expectation</em><br>Station.</h1><p>A little journey. A world of good choices.<br>Choose a school stop and discover the FALCON way.</p></div><div><div class="hero-art" role="img" aria-label="A friendly Falcon conductor beside a vintage train"></div><p class="hero-caption">YOUR NEXT GREAT CHOICE STARTS HERE</p></div></section><section class="board" aria-label="Station departure board"><div class="board-heading"><h2>Departures</h2><span>ALL ROUTES · THE FALCON WAY</span></div><div class="flaps" aria-hidden="true"></div><p class="board-note">11 school stops. One FALCON way. Choose your destination below.</p></section><section id="destinations"><div class="section-head"><div><span class="eyebrow">WHERE SHALL WE GO?</span><h2>Choose your next stop.</h2></div><p>Pick a picture. Board the train. Let’s learn!</p></div><div class="destinations">${stops.map((s,i)=>`<button class="destination" data-stop="${i}" aria-label="Board the train to ${s.name}">${scene(i)}<span class="dest-body"><span class="platform">PLATFORM ${String(i+1).padStart(2,'0')}</span><h3>${s.name}</h3><span class="board-btn">Board the train <span class="ticket" aria-hidden="true">✦</span></span></span></button>`).join('')}</div></section><div class="values">${labels.map(l=>`<span><b>${l[0]}</b>${l}</span>`).join('')}</div>`;
 main.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>board(+b.dataset.stop));let index=0;flaps('ALL ABOARD!');timer=setInterval(()=>{if(!reduced)flaps(stops[index++%stops.length].name)},4000);
}
function flaps(text){const el=document.querySelector('.flaps');if(el)el.innerHTML=[...text.slice(0,30)].map((c,i)=>`<span class="flap ${reduced?'':'flip'}" style="animation-delay:${i*15}ms">${c===' '?'&nbsp;':c==='&'?'&amp;':c}</span>`).join('')}
function board(i){window.speechSynthesis?.cancel();clearTimeout(travelTimer);if(reduced){location.hash=`stop/${i+1}`;return}document.querySelector('#travel-name').textContent=stops[i].name;document.querySelector('#journey').hidden=false;travelTimer=setTimeout(()=>{document.querySelector('#journey').hidden=true;location.hash=`stop/${i+1}`},1000)}
function stop(i){clearInterval(timer);const s=stops[i];main.innerHTML=`<button class="back" id="back">Back to the station</button><section class="stop-hero"><div><span class="eyebrow">PLATFORM ${String(i+1).padStart(2,'0')} · THE FALCON WAY</span><h1 tabindex="-1">${s.name}</h1><p>I can show the FALCON way every day!</p><div class="stop-actions"><button class="primary" id="read">Read aloud</button><button class="secondary" id="stop-reading" hidden>Stop reading</button></div></div>${scene(i,'scene stop-picture')}</section><section class="expectations" aria-label="FALCON expectations">${s.expectations.map((e,j)=>`<article class="expectation"><span class="letter" aria-hidden="true">${labels[j][0]}</span><div><h2>${labels[j]}</h2><p>${e}</p></div></article>`).join('')}</section><div class="stop-nav"><button class="secondary" id="station">Choose another stop</button><button class="primary" id="next">Next stop: ${stops[(i+1)%stops.length].name}</button></div>`;
 document.querySelector('#back').onclick=document.querySelector('#station').onclick=()=>location.hash='destinations';document.querySelector('#next').onclick=()=>board((i+1)%stops.length);
 const read=document.querySelector('#read'),cancel=document.querySelector('#stop-reading');if(!('speechSynthesis'in window)){read.hidden=true}else{read.onclick=()=>{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(`${s.name}. I can show the FALCON way every day! ${s.expectations.map((e,j)=>`${labels[j]}. ${e}`).join(' ')}`);u.rate=.8;u.onend=u.onerror=()=>{cancel.hidden=true;read.textContent='Read aloud'};speechSynthesis.speak(u);cancel.hidden=false;read.textContent='Read again'};cancel.onclick=()=>{speechSynthesis.cancel();cancel.hidden=true;read.textContent='Read aloud'}}
}
function render(){window.speechSynthesis?.cancel();document.querySelector('#journey').hidden=true;const m=location.hash.match(/^#stop\/(\d+)$/);if(m&&+m[1]>0&&+m[1]<=stops.length){stop(+m[1]-1);window.scrollTo(0,0);main.querySelector('h1').focus({preventScroll:true})}else{home();if(location.hash==='#destinations')document.querySelector('#destinations').scrollIntoView();else window.scrollTo(0,0)}}
window.addEventListener('hashchange',render);fetch('data.json').then(r=>r.json()).then(d=>{stops=d;render()}).catch(()=>main.innerHTML='<p>The station could not load. Please refresh to try again.</p>');
